class BSTIterator {
    private final List<Integer> values = new ArrayList<>();
    private int i = 0;

    BSTIterator(TreeNode root) {
        inorder(root);
    }

    private void inorder(TreeNode node) {
        if (node == null) return;
        inorder(node.left);
        values.add(node.val);
        inorder(node.right);
    }

    int next() {
        return values.get(i++);
    }

    boolean hasNext() {
        return i < values.size();
    }
}

