class BSTIterator {
  constructor(root) {
    this.stack = [];
    this.pushLeft(root);
  }

  pushLeft(node) {                         // the node and its whole left spine
    while (node !== null) {
      this.stack.push(node);
      node = node.left;
    }
  }

  next() {
    const node = this.stack.pop();         // the smallest value not yet returned
    this.pushLeft(node.right);             // its right subtree comes next
    return node.val;
  }

  hasNext() {
    return this.stack.length > 0;
  }
}

class BSTIterator:
    def __init__(self, root):
        self.stack = []
        self.push_left(root)

    def push_left(self, node):            # the node and its whole left spine
        while node is not None:
            self.stack.append(node)
            node = node.left

    def next(self):
        node = self.stack.pop()           # the smallest value not yet returned
        self.push_left(node.right)        # its right subtree comes next
        return node.val

    def hasNext(self):
        return len(self.stack) > 0

class BSTIterator {
    private final Deque<TreeNode> stack = new ArrayDeque<>();

    BSTIterator(TreeNode root) {
        pushLeft(root);
    }

    private void pushLeft(TreeNode node) {           // the node and its whole left spine
        while (node != null) {
            stack.push(node);
            node = node.left;
        }
    }

    int next() {
        TreeNode node = stack.pop();                 // the smallest value not yet returned
        pushLeft(node.right);                        // its right subtree comes next
        return node.val;
    }

    boolean hasNext() {
        return !stack.isEmpty();
    }
}

class BSTIterator {
    stack<TreeNode*> st;

    void pushLeft(TreeNode* node) {                  // the node and its whole left spine
        while (node != nullptr) {
            st.push(node);
            node = node->left;
        }
    }

public:
    BSTIterator(TreeNode* root) {
        pushLeft(root);
    }

    int next() {
        TreeNode* node = st.top();                   // the smallest value not yet returned
        st.pop();
        pushLeft(node->right);                       // its right subtree comes next
        return node->val;
    }

    bool hasNext() {
        return !st.empty();
    }
};
